const fs = require("fs");
eval(fs.readFileSync("routes-data.js", "utf8") + ";global.D={PURPOSES,TESTS,TYPES,DEFAULT_ROUTES,TEST_CATS,RESULTS,QC_PROFILES}");
const { PURPOSES, TESTS, TYPES, DEFAULT_ROUTES: R0, TEST_CATS, RESULTS: RES, QC_PROFILES: QCP } = D;
// Action and permit limits are default settings in app10-a.js (src/ in the shared folder, or this folder).
const appA = ["src/app10-a.js", "app10-a.js"].find(f => fs.existsSync(f));
const LIMITS = appA ? eval("[" + fs.readFileSync(appA, "utf8").match(/limits: \[([\s\S]*?)\n  \],/)[1] + "]") : [];
const sym = a => /^[A-Z][a-z]?$/.test(a.k) ? a.k : lcFirst(a.n);
const lcFirst = t => /^[A-Z][a-z]/.test(t) ? t.charAt(0).toLowerCase() + t.slice(1) : t;
const rank = r => TESTS.findIndex(t => t.key === r.tests[0]);
const R = R0.slice().sort((a, b) => rank(a) - rank(b));
const hl = h => h >= 48 ? `${+(h / 24).toFixed(1)} days` : `${+(+h).toFixed(2)} h`;
const dl = d => d === 365 ? "12 months" : d >= 30 && d % 30 === 0 ? `${d / 30} month${d === 30 ? "" : "s"}` : d >= 7 && d % 7 === 0 ? `${d / 7} week${d === 7 ? "" : "s"}` : `${d} days`;
const lc = t => t.charAt(0).toLowerCase() + t.slice(1);
const ret = x => +x.days ? `${x.item}: kept ${dl(x.days)} after results, then ${lc(x.then)}` : `${x.item}: ${lc(x.then)}`;
const PH = { intake: "Intake", prep: "Preparation", test: "Analysis / test", qc: "QA/QC" };
const tat = r => 1 + r.stages.reduce((t, x) => t + x.hours, 0);
const test = k => TESTS.find(t => t.key === k)?.name || k;
const type = k => TYPES.find(t => t.key === k)?.name || k;
const pur = k => PURPOSES.find(p => p.key === k)?.name || k;
const cell = s => String(s).replace(/\|/g, "\\|");
const slug = r => (r.code + " " + r.name).toLowerCase().replace(/[^a-z0-9 -]/g, "").trim().replace(/\s+/g, "-");
let o = [];
o.push("# Assay Lab workflow routes", "");
o.push("Default route library in the Assay Lab Sample Tracker prototype (https://claude.ai/artifact/5JgoyE2wokT67u8TCtYDop). Admins can change any of it on the Settings tab; samples already in the lab keep the steps they started with.", "");
o.push("## How a route is chosen", "");
o.push("1. The submitter picks the **sample type**, the **assay purpose** (why it is tested) and the **test requested**. The test list puts the tests recommended for that sample type first, and the purpose can change the default (for example drill core for metallurgical testwork defaults to a bottle roll).");
o.push("2. The page picks the route that performs that test. When several do, a route made for the purpose wins first, then one made for the sample type (for example fire assay of RC chips for grade control goes to the grade control fast track, GC-FA).");
o.push("3. At receipt the lab technician confirms the route or changes it. Later, a technician can change the route mid-way (for example an over-range result moving to FA-GRAV) or send the sample back for re-assay.", "");
o.push("Every route starts with **1. Submitted, awaiting receipt** (6 h allowed) and **2. Received & logged at lab** (1 h; bag checked against the submission, written to the inbound ledger). Every route ends with **Results released**, **Retained in storage** for the route's retention period, then **Returned**, **Sent to external lab** or **Disposed** (outbound ledger). \"Results after receipt\" below adds up the hours from receipt to results.", "", "Hours are clock hours while the lab runs round the clock (the default). When an admin enters lab working days and shifts on the Settings tab, hands-on steps count only working time and wait for the next shift; steps marked **round the clock** (drying ovens, leaches, curing, the umpire lab) keep running overnight and at weekends.", "");
o.push("## Results and lab batches", "");
o.push("Each test reports a fixed set of results (below, per route). Routes with a **lab batch** assay their samples in batches with reference materials (CRMs or check standards), blanks and duplicates placed automatically. A sample joins one batch for each analytical method its route uses (for example a solution AAS run for solution gold and a fire assay batch for solids), and a multi-element batch judges every element it reports on every QC position. The number of QC positions is fixed per batch, whatever its size. The batch QC is checked when its results are saved, and a sample's results can't go to QA/QC review without batch results or be released until the batch passes (or a lab supervisor accepts its warnings, or the lab manager accepts a failure as a documented exception). Routes without a batch check each sample's own results (balances, repeats, limits). A lab supervisor who did not enter the results releases them with a numbered certificate of analysis (ID-R1) carrying a check code; the lab manager may release their own with a recorded reason. A correction is proposed by one person and approved by a second, goes through the same range, check and limit tests as a first release, and issues an amended certificate (R2); earlier versions stay on record. Results worked out from others (recoveries, totals, calculated heads, NNP) are calculated, never typed; values below the detection limit count as 0 in them.", "", "Reference materials judged in SD are also watched across batches: two results in a row beyond 2 SD on the same side make the batch a warning, and nine in a row on one side of the certified value are flagged as a bias. Each result keeps the certified value it was judged on. A result past an **action or permit limit** (listed per route below; admins edit them on the Settings tab) raises an alert on the sample and the board, and the release waits until someone records what was done and who was told.", "");
o.push("| Batch type | Prefix | Size | QC positions | CRM rule | Blank | Duplicates |", "|---|---|---|---|---|---|---|");
const crmRule = p => !p.crm ? "—" : p.crm.mode === "sd" ? (p.crm.fail > p.crm.warn ? `±${p.crm.warn} SD pass, ${p.crm.warn}–${p.crm.fail} SD warning` : `±${p.crm.warn} SD`) : p.crm.mode === "pct" ? `±${p.crm.tol}%` : p.crm.mode === "rec" ? `${p.crm.lo}–${p.crm.hi}% recovery` : `±${p.crm.tol} (absolute)`;
const insText = p => [["pb", "prep blank"], ["cd", "crusher dup"], ["pd", p.all ? "" : "pulp dup"], ["crm", "CRM"], ["bl", "blank"]].filter(([k, l]) => l && p.ins?.[k]).map(([k, l]) => `${p.ins[k]} ${l}`).concat(p.all ? [p.all === 2 ? "every sample in triplicate" : "every sample in duplicate"] : []).join(", ");
for (const [k, p] of Object.entries(QCP)) o.push(`| ${cell(p.name)} | ${p.prefix} | ${p.size} | ${cell(insText(p))} | ${cell(crmRule(p))} | ${p.blank ? `< ${p.blank}× DL` : "—"}${p.pbBlank && p.pbBlank !== p.blank ? `; prep blank < ${p.pbBlank}× DL` : ""} | ${p.dupAbs ? `within ${p.dupAbs} absolute` : p.pd ? `${p.pd}%${p.cd ? ` (crusher ${p.cd}%)` : ""}${p.dupMin ? `, above ${p.dupMin}× DL` : ""}` : "—"} |`);
o.push("", "The reference materials and their certified values are kept on the Settings tab. The prototype ships with example values that must be replaced with the lab's own certificates.", "");
o.push("## Test catalogue", "");
for (const c of TEST_CATS) o.push(`- **${c}:** ${TESTS.filter(t => t.cat === c).map(t => t.name).join("; ")}`);
o.push("", "## Summary", "");
o.push("| Category | Route | Name | Lab steps | Results after receipt |", "|---|---|---|---|---|");
for (const r of R) o.push(`| ${TESTS[rank(r)].cat} | ${r.code} | ${cell(r.name)} | ${r.stages.length} | ${hl(tat(r))} |`);
o.push("", "## Sample types, recommended tests and receipt checks", "");
o.push("| Sample type | Recommended tests (first is the default) | Details asked at submission | Checked at receipt |", "|---|---|---|---|");
for (const t of TYPES) o.push(`| ${cell(t.name)} | ${cell(t.tests.map(test).join("; "))} | ${cell(t.fields.map(f => f.l).join(", ") || "—")} | ${cell(t.check)} |`);
o.push("", "Purposes: " + PURPOSES.map(p => p.name).join("; ") + ".", "");
o.push("## Routes", "");
let lastCat = "";
for (const r of R){
  const cat = TESTS[rank(r)].cat; if (cat !== lastCat){ o.push(`## ${cat}`, ""); lastCat = cat; }
  o.push(`### ${r.code}: ${r.name}`, "", r.desc, "");
  const types = r.types.filter(k => k !== "*").map(type);
  o.push(`- **Test:** ${r.tests.map(test).join(", ")}`);
  o.push(`- **Sample types:** ${types.join(", ")}${r.types.includes("*") ? (types.length ? ", and any other type" : "Any type") : ""}`);
  if (r.purposes.length) o.push(`- **Chosen first when the purpose is:** ${r.purposes.map(pur).join(", ")}`);
  o.push(`- **Results:** about ${hl(tat(r))} after receipt`);
  const res = RES[r.tests[0]];
  if (res) o.push(`- **Reports:** ${res.an.map(a => `${a.n}${a.u ? ` (${a.u})` : ""}${a.dl != null ? `, DL ${a.dl}` : ""}${a.ul != null ? `, range to ${a.ul}` : ""}${a.t === "pick" ? `: one of ${a.opts.join(", ")}` : ""}${a.calc ? `, calculated from ${a.from.map(k => lcFirst(res.an.find(x => x.k === k)?.n || k)).join(", ")}` : ""}${a.opt ? ", optional" : ""}`).join("; ")}`);
  if (res?.chk?.length) o.push(`- **Checks on each sample's results:** ${res.chk.map(c => c.msg.replace(/^the /, "")).join("; ")} hold the release${res.chk.some(c => c.soft) ? " (except those marked as reported only)" : ""} until re-assayed or accepted by a lab supervisor with a reason`);
  const gs = r.qcg || [];
  o.push(`- **Lab batch${gs.length > 1 ? "es" : ""}:** ${gs.length ? gs.map(g => `${QCP[g.p].name} for ${g.k.map(k => sym(res.an.find(a => a.k === k) || { k, n: k })).join(", ")}`).join("; ") : "none; checks run on each sample's own results"}`);
  const lims = LIMITS.filter(l => l.route === r.code), an = k => res?.an.find(a => a.k === k) || { n: k, u: "" };
  if (lims.length) o.push(`- **Action limits${lims.some(l => l.permit) ? " (permit values are examples)" : ""}:** ${lims.map(l => `${an(l.k).n} ${l.op === "<" ? "below" : "above"} ${l.val}${an(l.k).u ? " " + an(l.k).u : ""}${l.when ? ` (${l.when})` : ""}${l.permit ? " (permit)" : ""}: ${lc(l.act)}`).join("; ")}`);
  o.push("");
  o.push("| # | Step | Phase | Time allowed | Method and checks |", "|---|---|---|---|---|");
  r.stages.forEach((x, i) => o.push(`| ${i + 3} | ${cell(x.name)} | ${PH[x.phase]} | ${hl(x.hours)}${x.clock ? ", round the clock" : ""} | ${cell((x.note || "") + (x.redo ? `${x.note ? " " : ""}**Re-assays restart here.**` : ""))} |`));
  o.push("", `**QA/QC:** ${r.qc}`, "", "**Re-assay triggers**", "", ...r.triggers.map(t => `- ${t}`), "", "**Retention and disposal**", "", ...r.retention.map(x => `- ${ret(x)}`), "");
}
const out = process.env.OUT || "/mnt/project-files/sample-tracking/workflow-routes.md";
fs.mkdirSync("/mnt/project-files/sample-tracking", { recursive: true });
fs.writeFileSync(out, o.join("\n"));
console.log(out, o.length, "lines");
